const { fonte, janela } = $json;
const VERSAO_DA_API_META = 'v26.0';
const versaoApi = VERSAO_DA_API_META;
const FUSO = 'America/Sao_Paulo';
const datasetId = String(fonte?.externalId ?? '');

function deslocamento(instante) {
  const partes = new Intl.DateTimeFormat('en-US', {
    timeZone: FUSO, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  }).formatToParts(instante);
  const valor = (tipo) => Number(partes.find((parte) => parte.type === tipo)?.value);
  const comoUtc = Date.UTC(valor('year'), valor('month') - 1, valor('day'), valor('hour'), valor('minute'), valor('second'));
  return comoUtc - Math.floor(instante.getTime() / 1000) * 1000;
}

function meiaNoite(dia) {
  const [ano, mes, diaDoMes] = dia.split('-').map(Number);
  const ingenuo = Date.UTC(ano, mes - 1, diaDoMes);
  const primeira = ingenuo - deslocamento(new Date(ingenuo));
  return Math.floor((ingenuo - deslocamento(new Date(primeira))) / 1000);
}

const [ano, mes, dia] = janela.end.split('-').map(Number);
const diaSeguinte = new Date(Date.UTC(ano, mes - 1, dia + 1)).toISOString().slice(0, 10);
const startTime = meiaNoite(janela.start);
const endTime = meiaNoite(diaSeguinte);
const raiz = `https://graph.facebook.com/${versaoApi}/${encodeURIComponent(datasetId)}`;
const intervalo = `start_time=${startTime}&end_time=${endTime}`;
const base = `${raiz}/stats?aggregation=event&${intervalo}`;
const RECORTES = {"dispositivo":"device_type","sistema_operacional":"device_os","navegador_do_visitante":"browser_type","host":"host","chave_de_correspondencia":"match_keys","resultado_do_processamento":"event_processing_results"};
const recortes = Object.fromEntries(Object.entries(RECORTES).map(([nome, agregacao]) => [nome, `${raiz}/stats?aggregation=${agregacao}&${intervalo}`]));
const urlDoDataset = `${raiz}?fields=id,name,is_unavailable,enable_automatic_matching,first_party_cookie_status,data_use_setting`;

return [{
  json: {
    inicio: Date.now(),
    versaoApi,
    janela,
    datasetIdValido: /^\d{5,25}$/.test(datasetId),
    startTime,
    endTime,
    urls: {
      total: base,
      navegador: `${base}&event_source=WEB_ONLY`,
      servidor: `${base}&event_source=SERVER_ONLY`,
    },
    recortes,
    urlDoDataset,
  },
}];

const contexto = $('Montar requisição').first().json;
const FUSO = 'America/Sao_Paulo';
const ORIGENS = ['total', 'navegador', 'servidor'];
const NO_DA_ORIGEM = { total: 'Eventos (total)', navegador: 'Eventos (navegador)', servidor: 'Eventos (servidor)' };
const TAMANHO_MAXIMO_DO_EVENTO = 200;

const respostasPorOrigem = {};
for (const origem of ORIGENS) {
  respostasPorOrigem[origem] = $(NO_DA_ORIGEM[origem]).all()
    .map((item) => item.json)
    .filter((json) => json && (json.statusCode !== undefined || json.error));
}
const RECORTES = {"dispositivo":"Recorte (dispositivo)","sistema_operacional":"Recorte (sistema operacional)","navegador_do_visitante":"Recorte (navegador do visitante)","host":"Recorte (host)","chave_de_correspondencia":"Recorte (chaves de correspondência)","resultado_do_processamento":"Recorte (resultado do processamento)"};
function respostasDe(nome) {
  try {
    return $(nome).all().map((item) => item.json).filter((json) => json && (json.statusCode !== undefined || json.error));
  } catch {
    return [];
  }
}
const respostasDosRecortes = Object.fromEntries(Object.entries(RECORTES).map(([recorte, no]) => [recorte, respostasDe(no)]));
const respostasDoDataset = respostasDe('Dataset');
const todas = [
  ...ORIGENS.flatMap((origem) => respostasPorOrigem[origem]),
  ...Object.values(respostasDosRecortes).flat(),
  ...respostasDoDataset,
];
const requests = todas.length;
const bytes = todas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

const PAUSA_DO_USO_META = 75;
const CODIGOS_DE_LIMITE_META = [4, 17, 32, 341, 613];
function limiteDaMeta(statusCode, erro) {
  const codigo = Number(erro?.code);
  return statusCode === 429 || CODIGOS_DE_LIMITE_META.includes(codigo) || (codigo >= 80000 && codigo <= 80014)
    || /request limit reached|too many calls|rate limit/i.test(String(erro?.message ?? ''));
}
function lerJson(valor) {
  if (valor && typeof valor === 'object') return valor;
  try {
    return typeof valor === 'string' ? JSON.parse(valor) : null;
  } catch {
    return null;
  }
}
function cabecalho(resposta, nome) {
  const cabecalhos = resposta?.headers ?? {};
  return cabecalhos[nome] ?? cabecalhos[nome.toLowerCase()] ?? null;
}
function usoDaMeta(respostas) {
  let percentual = null;
  let minutosParaRecuperar = 0;
  for (const resposta of respostas) {
    const throttle = lerJson(cabecalho(resposta, 'x-fb-ads-insights-throttle'));
    const negocio = lerJson(cabecalho(resposta, 'x-business-use-case-usage'));
    const aplicativo = lerJson(cabecalho(resposta, 'x-app-usage'));
    const entradas = negocio ? Object.values(negocio).flat() : [];
    const valores = [
      throttle?.acc_id_util_pct, throttle?.app_id_util_pct,
      aplicativo?.call_count, aplicativo?.total_cputime, aplicativo?.total_time,
      ...entradas.flatMap((entrada) => [entrada?.call_count, entrada?.total_cputime, entrada?.total_time]),
    ].map(Number).filter(Number.isFinite);
    if (valores.length > 0) percentual = Math.max(percentual ?? 0, ...valores);
    for (const entrada of entradas) {
      const minutos = Number(entrada?.estimated_time_to_regain_access);
      if (Number.isFinite(minutos)) minutosParaRecuperar = Math.max(minutosParaRecuperar, minutos);
    }
  }
  return { percentual, minutosParaRecuperar };
}
function avisosDaMeta(respostas, versaoApi) {
  const avisos = [];
  const servidas = new Set(respostas.map((resposta) => cabecalho(resposta, 'facebook-api-version')).filter(Boolean).map(String));
  for (const servida of servidas) {
    if (servida !== versaoApi) avisos.push({ tipo: 'versao_da_api', detalhe: `pedida ${versaoApi}, servida ${servida}` });
  }
  const alerta = respostas.map((resposta) => cabecalho(resposta, 'x-ad-api-version-warning')).find(Boolean);
  if (alerta) avisos.push({ tipo: 'versao_da_api', detalhe: String(alerta).slice(0, 500) });
  const uso = usoDaMeta(respostas);
  if (uso.percentual !== null && uso.percentual > PAUSA_DO_USO_META) {
    avisos.push({ tipo: 'uso_de_cota', detalhe: `uso da Meta em ${uso.percentual}%${uso.minutosParaRecuperar ? `, recupera em ${uso.minutosParaRecuperar} min` : ''}` });
  }
  return avisos;
}

const avisos = avisosDaMeta(todas, contexto.versaoApi);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      avisos,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

function falhaDe(respostas) {
  if (respostas.length === 0) return { causa: 'api_recusou', detalhe: 'a Meta não respondeu' };
  const deRede = respostas.find((resposta) => resposta.error);
  if (deRede) {
    const detalhe = deRede.error?.message ?? String(deRede.error);
    return { causa: 'api_recusou', detalhe: `falha de rede: ${detalhe}`.replace(/access_token=[^&\s"']+/g, 'access_token=[removido]').slice(0, 500) };
  }
  const recusada = respostas.find((resposta) => !(resposta.statusCode >= 200 && resposta.statusCode < 300));
  if (!recusada) return null;
  const erro = recusada.body?.error;
  const detalhe = String(erro?.message || `HTTP ${recusada.statusCode}`).replace(/access_token=[^&\s"']+/g, 'access_token=[removido]').slice(0, 500);
  if (limiteDaMeta(recusada.statusCode, erro)) return { causa: 'limite_de_uso', detalhe };
  const semAcesso = recusada.statusCode === 401 || recusada.statusCode === 403 || [190, 10, 200].includes(erro?.code);
  return { causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe };
}

if (!contexto.datasetIdValido) return devolver([], [{ causa: 'api_recusou', detalhe: 'id do conjunto de dados inválido' }]);

const falhaDoTotal = falhaDe(respostasPorOrigem.total);
if (falhaDoTotal) return devolver([], [falhaDoTotal]);

const formatoDoDia = new Intl.DateTimeFormat('en-CA', { timeZone: FUSO, year: 'numeric', month: '2-digit', day: '2-digit' });

function instanteDoBalde(valor) {
  if (typeof valor === 'number' && Number.isFinite(valor)) return new Date(valor * 1000);
  if (typeof valor !== 'string' || !valor) return null;
  if (/^\d+$/.test(valor)) return new Date(Number(valor) * 1000);
  const data = new Date(valor.replace(/([+-]\d{2})(\d{2})$/, '$1:$2'));
  return Number.isNaN(data.getTime()) ? null : data;
}

function nomeDoEvento(valor) {
  if (typeof valor !== 'string') return null;
  const limpo = valor.trim();
  return limpo ? limpo.slice(0, TAMANHO_MAXIMO_DO_EVENTO) : null;
}

function contagem(valor) {
  const numero = typeof valor === 'string' && valor.trim() !== '' ? Number(valor) : valor;
  return typeof numero === 'number' && Number.isFinite(numero) && numero >= 0 ? Math.trunc(numero) : null;
}

function agregar(respostas, origem) {
  const somas = new Map();
  for (const resposta of respostas) {
    const baldes = Array.isArray(resposta.body?.data) ? resposta.body.data : [];
    for (const balde of baldes) {
      const instante = instanteDoBalde(balde?.start_time);
      if (!instante || !Array.isArray(balde.data)) continue;
      const dataDia = formatoDoDia.format(instante);
      if (dataDia < contexto.janela.start || dataDia > contexto.janela.end) continue;
      for (const item of balde.data) {
        const evento = nomeDoEvento(item?.value);
        const quantidade = contagem(item?.count);
        if (!evento || quantidade === null) continue;
        const chave = `${dataDia}|${evento}`;
        const anterior = somas.get(chave);
        somas.set(chave, { dataDia, evento, origem, quantidade: (anterior?.quantidade ?? 0) + quantidade });
      }
    }
  }
  return [...somas.values()];
}

const HOST = /^[a-z0-9]([a-z0-9.-]{0,198}[a-z0-9])?$/;
const VALOR_ENUMERADO = /^[A-Za-z0-9_ .+-]{1,60}$/;
function valorDoRecorte(recorte, valor) {
  if (typeof valor !== 'string') return null;
  const limpo = valor.trim();
  if (recorte === 'host') {
    const host = limpo.toLowerCase().replace(/^[a-z]+:\/\//, '').split(/[/?#:]/)[0];
    return HOST.test(host) ? host : null;
  }
  return VALOR_ENUMERADO.test(limpo) ? limpo : null;
}

function agregarRecorte(respostas, recorte) {
  const somas = new Map();
  for (const resposta of respostas) {
    const baldes = Array.isArray(resposta.body?.data) ? resposta.body.data : [];
    for (const balde of baldes) {
      const instante = instanteDoBalde(balde?.start_time);
      if (!instante || !Array.isArray(balde.data)) continue;
      const dataDia = formatoDoDia.format(instante);
      if (dataDia < contexto.janela.start || dataDia > contexto.janela.end) continue;
      for (const item of balde.data) {
        const valor = valorDoRecorte(recorte, item?.value);
        const quantidade = contagem(item?.count);
        if (!valor || quantidade === null) continue;
        const chave = `${dataDia}|${valor}`;
        const anterior = somas.get(chave);
        somas.set(chave, { _tabela: 'recortes', dataDia, recorte, valor, quantidade: (anterior?.quantidade ?? 0) + quantidade });
      }
    }
  }
  return [...somas.values()];
}

function textoCurto(valor) {
  return typeof valor === 'string' && valor.trim() ? valor.trim().slice(0, TAMANHO_MAXIMO_DO_EVENTO) : null;
}
function booleano(valor) {
  return typeof valor === 'boolean' ? valor : null;
}

const linhas = [];
const origensIncompletas = [];
for (const origem of ORIGENS) {
  const falha = origem === 'total' ? null : falhaDe(respostasPorOrigem[origem]);
  if (falha) {
    origensIncompletas.push(`${origem}: ${falha.detalhe}`);
    continue;
  }
  linhas.push(...agregar(respostasPorOrigem[origem], origem));
}

for (const recorte of Object.keys(RECORTES)) {
  const falha = falhaDe(respostasDosRecortes[recorte]);
  if (falha) {
    origensIncompletas.push(`${recorte}: ${falha.detalhe}`);
    continue;
  }
  linhas.push(...agregarRecorte(respostasDosRecortes[recorte], recorte));
}

const limiteNosOpcionais = [
  ...ORIGENS.filter((origem) => origem !== 'total').map((origem) => falhaDe(respostasPorOrigem[origem])),
  ...Object.keys(RECORTES).map((recorte) => falhaDe(respostasDosRecortes[recorte])),
  falhaDe(respostasDoDataset),
].find((falha) => falha?.causa === 'limite_de_uso');

const falhaDoDataset = falhaDe(respostasDoDataset);
if (falhaDoDataset) {
  origensIncompletas.push(`dataset: ${falhaDoDataset.detalhe}`);
} else {
  const ficha = respostasDoDataset[0]?.body ?? {};
  const cookie = typeof ficha.first_party_cookie_status === 'string' && /^[A-Z_]{1,60}$/.test(ficha.first_party_cookie_status) ? ficha.first_party_cookie_status : null;
  const usoDeDados = typeof ficha.data_use_setting === 'string' && /^[A-Z_]{1,60}$/.test(ficha.data_use_setting) ? ficha.data_use_setting : null;
  linhas.push({
    _tabela: 'dim_dataset',
    nome: textoCurto(ficha.name),
    indisponivel: booleano(ficha.is_unavailable),
    correspondenciaAutomatica: booleano(ficha.enable_automatic_matching),
    cookiePrimeiraParte: cookie,
    usoDeDados,
  });
}

const interrompida = (respostas) => Boolean(respostas[respostas.length - 1]?.body?.paging?.next);
const consultasLidas = [
  ...ORIGENS.map((origem) => [origem, respostasPorOrigem[origem]]),
  ...Object.entries(respostasDosRecortes),
  ['dataset', respostasDoDataset],
];
for (const [nome, respostas] of consultasLidas) {
  if (interrompida(respostas)) origensIncompletas.push(`${nome}: paginação interrompida no limite de requisições`);
}

if (limiteNosOpcionais) return devolver(linhas, [limiteNosOpcionais]);
if (!linhas.some((linha) => linha.origem === 'total')) return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }]);
if (origensIncompletas.length > 0) {
  return devolver(linhas, origensIncompletas.map((detalhe) => ({ causa: 'coleta_incompleta', detalhe: detalhe.slice(0, 500) })));
}
return devolver(linhas, []);
